ATLAS = zlib.decompress(base64.b64decode(ATLAS_B64))
GD = json.loads(zlib.decompress(base64.b64decode(GLYPHS_B64)))
AW = GD["atlas_w"]
AH = GD["atlas_h"]
LINE_H = {"mast": 55, "lead": 41, "head2": 19, "kick": 14, "deck": 17, "body": 15, "tiny": 13}


def ginfo(style, ch):
    return GD["styles"][style]["glyphs"].get(ch)


def twidth(style, s):
    tot = 0
    for ch in s:
        g = ginfo(style, ch)
        if g is None:
            if ch == "Ü":
                g = ginfo(style, "U")
                tot += g[6] if g else 0
            else:
                g = ginfo(style, " ")
                tot += g[6] if g else 4
        else:
            tot += g[6]
    return tot


def wrap(style, s, maxw):
    words = s.split(" ")
    lines = []
    cur = ""
    for w in words:
        t = w if not cur else cur + " " + w
        if twidth(style, t) <= maxw or not cur:
            cur = t
        else:
            lines.append(cur)
            cur = w
    if cur:
        lines.append(cur)
    return lines

PAPER = (247, 243, 234)
INK = (20, 20, 20)
