CITYC = (240, 165, 150)
BODYC = (60, 58, 52)

W = 1024
H = 1024
PX = bytearray(bytes(PAPER) * (W * H))


def blend(x, y, col, a):
    if a <= 0 or x < 0 or y < 0 or x >= W or y >= H:
        return
    i = (y * W + x) * 3
    if a >= 255:
        PX[i] = col[0]
        PX[i + 1] = col[1]
        PX[i + 2] = col[2]
    else:
        PX[i] = (col[0] * a + PX[i] * (255 - a)) // 255
        PX[i + 1] = (col[1] * a + PX[i + 1] * (255 - a)) // 255
        PX[i + 2] = (col[2] * a + PX[i + 2] * (255 - a)) // 255


def rect(x0, y0, x1, y1, col):
    for yy in range(max(0, y0), min(H, y1)):
        for xx in range(max(0, x0), min(W, x1)):
            i = (yy * W + xx) * 3
            PX[i] = col[0]
            PX[i + 1] = col[1]
            PX[i + 2] = col[2]


def draw_char(style, ch, px, baseline, col):
    g = ginfo(style, ch)
    if g is None:
        return 0
    gx, gy, gw, gh, xoff, yoff, adv = g
    top = baseline + yoff
    left = px + xoff
    for row in range(gh):
        sy = gy + row
        dy = top + row
        if dy < 0 or dy >= H:
            continue
        base = sy * AW
        for cc in range(gw):
            v = ATLAS[base + gx + cc]
            if v:
                blend(left + cc, dy, col, v * 17)
    return adv


def draw_text(style, s, x, baseline, col):
    px = x
    for ch in s:
        if ch == "Ü":
            adv = draw_char(style, "U", px, baseline, col)
            g = ginfo(style, "U")
            if g:
                uw = g[2]
                top = baseline + g[5]
                cx = px + g[4]
                d1 = cx + max(1, uw // 4)
                d2 = cx + max(2, (3 * uw) // 4)
                for ddx in (d1, d2):
                    for ddy in range(top - 3, top - 1):
                        for ddx2 in range(ddx, ddx + 2):
                            blend(ddx2, ddy, col, 255)
            px += adv
        else:
            px += draw_char(style, ch, px, baseline, col)
    return px


def draw_right(style, s, xr, baseline, col):
    draw_text(style, s, xr - twidth(style, s), baseline, col)


def diamond(cx, cy, col):
    for dy in range(-2, 3):
        span = 2 - abs(dy)
        for dx in range(-span, span + 1):
            blend(cx + dx, cy + dy, col, 255)


def chunk(tag, data):
    c = struct.pack(">I", len(data)) + tag + data
    return c + struct.pack(">I", zlib.crc32(tag + data) & 0xFFFFFFFF)


def save_png(path):
    raw = bytearray()
    stride = W * 3
    for yy in range(H):
        raw.append(0)
        raw += PX[yy * stride:(yy + 1) * stride]
    png = b"\x89PNG\r\n\x1a\n"
    png += chunk(b"IHDR", struct.pack(">IIBBBBB", W, H, 8, 2, 0, 0, 0))
    png += chunk(b"IDAT", zlib.compress(bytes(raw), 6))
    png += chunk(b"IEND", b"")
    with open(path, "wb") as f:
        f.write(png)

