def draw_map(x0, y0, x1, y1):
    rect(x0, y0, x1, y1, MAPBG)
    cw = (x1 - x0) / 112.0
    chh = (y1 - y0) / 41.0
    for (r, c0, c1) in MAP_RUNS:
        cy = int(y0 + (r + 0.5) * chh)
        for c in range(c0, c1 + 1):
            cx = int(x0 + (c + 0.5) * cw)
            for ddy in range(-1, 2):
                for ddx in range(-1, 2):
                    if ddx == 0 or ddy == 0:
                        blend(cx + ddx, cy + ddy, MAPDOT, 255)
    for (lat, lon) in MARKERS:
        col = (lon + 180.0) / 360.0 * 112.0
        row = (90.0 - lat) / 180.0 * 41.0
        cx = int(x0 + col / 112.0 * (x1 - x0))
        cy = int(y0 + row / 41.0 * (y1 - y0))
        diamond(cx, cy, RED)


