def render_cards_briefs():
    colx = [36, 356, 676]
    colw = [312, 312, 308]
    for i, (kick, head, body) in enumerate(CARDS):
        cx = colx[i % 3]
        cw = colw[i % 3]
        top = 458 + (i // 3) * 104
        draw_text("kick", kick, cx, top + LINE_H["kick"], RED)
        hy = top + 16
        for ln in wrap("head2", head, cw)[:2]:
            hy += LINE_H["head2"]
            draw_text("head2", ln, cx, hy, INK)
        by = hy + 2
        for ln in wrap("body", body, cw)[:3]:
            by += LINE_H["body"]
            draw_text("body", ln, cx, by, BODYC)
    rect(354, 458, 355, 874, LINEC)
    rect(674, 458, 675, 874, LINEC)
    rect(0, 882, 1024, 978, NAVY)
    draw_text("kick", "AROUND THE WORLD IN BRIEF", 36, 882 + LINE_H["kick"], CITYC)
    for i, (city, txt) in enumerate(BRIEFS):
        cx = colx[i % 3]
        cw = colw[i % 3]
        top = 906 + (i // 3) * 27
        lines = wrap("tiny", txt, cw - twidth("tiny", city + " ") - 2)
        draw_text("tiny", city, cx, top + LINE_H["tiny"], CITYC)
        if lines:
            draw_text("tiny", lines[0], cx + twidth("tiny", city + " "), top + LINE_H["tiny"], WHITE)
        if len(lines) > 1:
            draw_text("tiny", lines[1], cx, top + 2 * LINE_H["tiny"], WHITE)
    ex = draw_text("kick", "SPORT", 36, 990 + LINE_H["kick"], RED)
    draw_text("head2", "Pant's 128 stuns New Zealand · Verstappen wins the Las Vegas Grand Prix", ex + 10, 990 + LINE_H["head2"], INK)
    draw_right("tiny", "24 November 2026 - Nvidia - Kyiv - Banten - Hormuz", 988, 990 + LINE_H["tiny"], GREY)


